<?php require_once '../includes/auth.php';login_required();$s=store();if(!$s)go('/seller/store.php');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$q=$pdo->prepare('UPDATE orders SET status=? WHERE id=? AND store_id=?');$q->execute([$_POST['status']??'pending',(int)$_POST['id'],$s['id']]);}$q=$pdo->prepare('SELECT * FROM orders WHERE store_id=? ORDER BY created_at DESC');$q->execute([$s['id']]);$os=$q->fetchAll();$title='Orders';require '../includes/header.php';?><h1>Orders</h1><?php foreach($os as $o):?><div class="card mb-3"><div class="card-body"><b>Order #<?=e($o['id'])?></b> — <?=e($o['customer_name'])?> — <?=money($o['total'])?><form method="post" class="d-flex gap-2 mt-2"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($o['id'])?>"><select name="status" class="form-select" style="max-width:220px"><?php foreach(['pending','confirmed','completed','cancelled'] as $x):?><option <?= $o['status']===$x?'selected':''?>><?=e($x)?></option><?php endforeach;?></select><button class="btn btn-success">Update</button></form></div></div><?php endforeach;?><?php require '../includes/footer.php';?>